class View:
    def __init__(self):
        self.rows = []
        self.notes = {}
        self.loading = False
        self.error = None
        self.seq = 0

    def begin(self, query):
        self.seq += 1
        self.loading = True
        self.error = None  # Clear errors on begin
        return self.seq

    def finish(self, id, rows):
        if not self.loading or self.seq != id:
            return False
        self.rows = rows.copy()
        self.loading = False
        return True
